"""Compose the unchanged local performer with the experimental ownership pedal."""
from pathlib import Path
import re
b=Path(__file__).resolve().parents[1]
source=(b/'rtl/local_performer.v').read_text()
header=source[source.index('module local_performer('):source.index(');')+2]
header=header.replace('module local_performer(', 'module local_pedal_performer #(parameter STABLE_CYCLES=250000)(').replace('output reg','output wire')
header=header.replace('\n);',',\n input wire [3:0] pedal_raw,output wire [3:0] pedal_down,output wire [15:0] deferred_returns\n);')
names=['clk','rst','panic','pad_valid','pad_ready','pad_off','pad_contact','pad_pressure','pad_serial','root','minor_mode','busy','status_part','status_valid','status_owner','status_epoch','command_valid','command_ready','command','command_part','command_source','manual_valid','manual_ready','manual_kind','manual_source','manual_contact','manual_part','manual_epoch','manual_serial','manual_note','manual_velocity','denied','held_contacts']
mapped={'command_valid':'raw_valid','command_ready':'raw_ready','command':'raw_command','command_part':'raw_part','command_source':'raw_source'}
body='\nwire raw_valid,raw_ready;wire [1:0] raw_command;wire [3:0] raw_part;wire [7:0] raw_source;\n'
body+='local_performer performer('+','.join('.'+n+'('+mapped.get(n,n)+')' for n in names)+');\n'
body+='pedal_command_gate #(.STABLE_CYCLES(STABLE_CYCLES)) pedal(clk,rst,panic,pedal_raw,raw_valid,raw_ready,raw_command,raw_part,raw_source,command_valid,command_ready,command,command_part,command_source,pedal_down,deferred_returns);\nendmodule\n'
out=b/'experimental/local_pedal';out.mkdir(exist_ok=True)
(out/'local_pedal_performer.v').write_text('// Generated by tools/prepare_local_pedal.py; source-only experimental integration.\n'+header+body)
